p='test/cycles.test.js'; s=open(p).read()
s=s.replace("cut to the cent","rounded to the nearest cent")
s=s.replace("11999, cycle: 'yearly' }), 999);","11999, cycle: 'yearly' }), 1000);")
s=s.replace("1450, cycle: 'yearly' }), 120);","1450, cycle: 'yearly' }), 121);")
s=s.replace("  assert.ok(CYCLES.includes('yearly'));\n","  assert.ok(CYCLES.includes('yearly'));\n  assert.ok(CYCLES.includes('weekly'));\n")
s=s.replace("test('the next charge of a plan that charges today","""test('a weekly plan costs its price x 52 / 12 a month, rounded to the nearest cent', () => {
  assert.equal(monthlyCents({ price: 5990, cycle: 'weekly' }), 25957);
