import { addDays, addMonths, daysBetween } from './dates.js';

/** Billing cycles a plan can have. */
export const CYCLE = Object.freeze({ WEEK: 'weekly', MONTH: 'monthly', YEAR: 'yearly' });

/** Every supported cycle, as stored in the subscriptions file. */
export const CYCLES = Object.freeze(Object.values(CYCLE));

const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };
const CHARGES_PER_YEAR = { [CYCLE.WEEK]: 52, [CYCLE.MONTH]: 12, [CYCLE.YEAR]: 1 };
const DAYS_PER_WEEK = 7;

/**
 * What a plan costs per month, in whole cents (rounded to the nearest cent).
 * @param {{ price: number, cycle: string }} sub
 * @returns {number}
 */
export function monthlyCents(sub) {
  return Math.round((sub.price * CHARGES_PER_YEAR[sub.cycle]) / 12);
}

/**
 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
 * Weekly plans charge every 7 days from the first charge (`since`); the others fall on the day of the month
 * of the first charge, or the last day of a shorter month.
 * @param {{ cycle: string, since: string }} sub
 * @param {string} today
 * @returns {string}
 */
export function nextCharge(sub, today) {
  if (sub.cycle === CYCLE.WEEK) {
    if (sub.since >= today) return sub.since;
    const weeks = Math.ceil(daysBetween(sub.since, today) / DAYS_PER_WEEK);
    return addDays(sub.since, weeks * DAYS_PER_WEEK);
  }
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}
